const extraSource=Promise.all(['motions.js','rigging.js','puppet.js','scene-fx.js','expanded-assets.js','expanded-effects.js','scene-weather.js','more-weather.js','productivity-assets.js','productivity-effects.js','effect-layout.js','night-story-assets.js','head-expressions.js','avatars.js','audio.js','expanded-audio.js','night-story-audio.js','quiet-story-renderer.js'].map(path=>fetch(path+'?v=20').then(r=>{if(!r.ok)throw Error('Could not load the export engine.');return r.text()})));extraSource.catch(()=>{});
exportHTML=async function(){try{const source=await engineSourcePromise,extra=(await extraSource).join('\n'),data=JSON.stringify(await MotionAudio.portable(project)).replace(/</g,'\\u003c');const html=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(project.name)}</title><style>*{box-sizing:border-box}body{margin:0;background:#171e23;color:#f3eee2;font:14px Arial;height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center}canvas{max-width:100%;max-height:calc(100vh - 70px);aspect-ratio:${project.format==='9:16'?'9/16':'16/9'};object-fit:contain}footer{height:60px;display:flex;align-items:center;gap:15px;width:min(900px,94vw)}button{border:0;background:#e98360;color:white;padding:10px 16px;border-radius:6px;cursor:pointer}input{flex:1;accent-color:#e98360}#message{font-size:11px;color:#b4bfc7}</style></head><body><canvas id="c" width="${project.format==='9:16'?1080:1920}" height="${project.format==='9:16'?1920:1080}"></canvas><footer><button id="play">▶ Play with sound</button><input id="seek" type="range" min="0" step="0.01" value="0" aria-label="Playback position"><span id="time"></span><button id="fs">⛶</button></footer><div id="message">Click Play to enable sound.</div><script>${source}\n${extra}<\/script><script>const p=${data},c=document.getElementById('c'),ctx=c.getContext('2d'),seek=document.getElementById('seek'),btn=document.getElementById('play');let total=p.frames.reduce((s,f)=>s+f.duration,0),t=0,run=false,last=performance.now(),stopAudio=null,sounds=null,busy=false;seek.max=total;async function audioStart(){stopAudio?.();if(!MotionAudio.cues(p).length)return;const ac=MotionAudio.getContext();await ac.resume();sounds=sounds||await MotionAudio.prepare(p,ac);stopAudio=MotionAudio.schedule(ac,sounds,t,ac.destination,ac.currentTime)}btn.onclick=async()=>{if(busy)return;if(run){run=false;stopAudio?.();btn.textContent='▶ Play';return}busy=true;try{await audioStart();last=performance.now();run=true;btn.textContent='Ⅱ Pause';document.getElementById('message').textContent=''}catch(e){document.getElementById('message').textContent='Audio unavailable: '+e.message}finally{busy=false}};seek.oninput=()=>{t=Number(seek.value);if(run)audioStart().catch(e=>document.getElementById('message').textContent=e.message)};document.getElementById('fs').onclick=()=>document.documentElement.requestFullscreen?.();Motion.ready(p).then(()=>requestAnimationFrame(function tick(now){if(run){t+=(now-last)/1000;if(t>=total){t%=total;audioStart().catch(()=>{})}}last=now;Motion.render(ctx,Motion.sample(p,t),t);seek.value=t;document.getElementById('time').textContent=t.toFixed(1)+' / '+total.toFixed(1)+'s';requestAnimationFrame(tick)}));<\/script></body></html>`;download(new Blob([html],{type:'text/html'}),safeName()+'.html');toast('HTML exported with characters, camera moves and sound.')}catch(e){toast(e.message)}};
realtimeVideo=async function(p,width,height,signal,onProgress){if(!window.MediaRecorder)throw Error('This browser does not support recording.');const hasAudio=MotionAudio.cues(p).length>0,types=hasAudio?['video/mp4;codecs=avc1.42E01E,mp4a.40.2','video/mp4','video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm']:['video/mp4;codecs=avc1','video/mp4','video/webm;codecs=vp9','video/webm'];const type=types.find(v=>MediaRecorder.isTypeSupported(v));if(!type)throw Error('No compatible video recorder is available.');if(!type.startsWith('video/mp4'))$('#exportStatus').textContent='MP4 is unavailable in this browser. Exporting WebM with sound.';const c=document.createElement('canvas');c.width=width;c.height=height;const cx=c.getContext('2d',{alpha:false});await M.ready(p);const ac=hasAudio?MotionAudio.getContext():null;if(ac)await ac.resume();const list=hasAudio?await MotionAudio.prepare(p,ac):[],dest=ac?.createMediaStreamDestination(),stream=c.captureStream(p.fps);dest?.stream.getAudioTracks().forEach(t=>stream.addTrack(t));M.render(cx,M.sample(p,0),0,width,height);const recorder=new MediaRecorder(stream,{mimeType:type,videoBitsPerSecond:8e6,audioBitsPerSecond:192000}),chunks=[],total=p.frames.reduce((a,f)=>a+f.duration,0);if(signal.aborted){stream.getTracks().forEach(t=>t.stop());throw Error('Export cancelled.')}return new Promise((resolve,reject)=>{let timer,start=0,error=null,stopSounds=null;const clean=()=>{clearTimeout(timer);stopSounds?.();stream.getTracks().forEach(t=>t.stop());signal.removeEventListener('abort',cancel);dest?.disconnect()};const cancel=()=>{error=Error('Export cancelled.');if(recorder.state!=='inactive')recorder.stop();else{clean();reject(error)}};signal.addEventListener('abort',cancel);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onerror=e=>{error=e.error||Error('Recording failed.');clean();reject(error)};recorder.onstop=()=>{clean();error?reject(error):resolve(new Blob(chunks,{type:recorder.mimeType||type}))};recorder.start(1000);if(ac)stopSounds=MotionAudio.schedule(ac,list,0,dest,ac.currentTime);start=performance.now();function step(){if(signal.aborted)return;const t=(performance.now()-start)/1000;M.render(cx,M.sample(p,Math.min(total-.000001,t)),Math.min(t,total),width,height);onProgress(Math.min(1,t/total));if(t>=total){recorder.stop();return}timer=setTimeout(step,1000/p.fps)}step()})};
$('#cameraBtn').onclick=()=>{setTool(tool==='camera'?'select':'camera');renderInspector();if(tool==='camera')$('#camera-panel').scrollIntoView({block:'start',behavior:'smooth'})};
renderLibrary();refreshUI();
Studio.importSound=()=>importSound(false);Studio.soundLibrary=soundLibrary;
window.MotionroomTest={...window.MotionroomTest,validateProject,openBuilder,cameraPanel,allSounds};
